export declare function StoryStudioApp(): import("react").JSX.Element;
export declare const storyStudioAppStyles = "\n/* \u9690\u85CF AdvancedFrame \u7684\u9ED8\u8BA4\u7EC4\u4EF6 */\n.dshDesktopSidebarSurface {\n  display: none !important;\n}\n\n.dshDesktopFrame > aside {\n  display: none !important;\n}\n\n/* ============================================================\n   Story Studio \u00B7 Bento \u5361\u7247\u5F0F\u5DE5\u4F5C\u53F0\n   ============================================================ */\n:root {\n  --ss-bg: #EEEEF0;\n  --ss-bg-2: #F5F5F7;\n  --ss-surface: #FFFFFF;\n  --ss-surface-2: #FAFAFC;\n  --ss-dark: #1D1D1F;\n  --ss-dark-2: #2C2C2E;\n  --ss-ink: #1D1D1F;\n  --ss-text: #424245;\n  --ss-muted: #6E6E73;\n  --ss-faint: #AEAEB2;\n  --ss-hairline: #E8E8ED;\n  --ss-hairline-strong: #D8D8E0;\n  --ss-brand: #0071E3;\n  --ss-brand-hover: #0077ED;\n  --ss-brand-deep: #0062C4;\n  --ss-brand-soft: #EAF2FE;\n  --ss-green: #1FA958;\n  --ss-green-soft: #EAF8F0;\n  --ss-orange: #F08A24;\n  --ss-orange-soft: #FDF3E7;\n  --ss-shadow-sm: 0 1px 2px rgba(0, 0, 0, .05);\n  --ss-shadow: 0 2px 8px rgba(0, 0, 0, .05), 0 12px 32px rgba(0, 0, 0, .06);\n  --ss-shadow-float: 0 8px 24px rgba(0, 0, 0, .10), 0 2px 8px rgba(0, 0, 0, .07);\n  --ss-shadow-paper: 0 2px 8px rgba(0, 0, 0, .06), 0 24px 48px rgba(0, 0, 0, .10);\n  --ss-r-card: 22px;\n  --ss-r-lg: 28px;\n  --ss-r-md: 16px;\n  --ss-r-sm: 12px;\n  --ss-r-pill: 100px;\n  --ss-sans: 'Geist', 'Inter', -apple-system, BlinkMacSystemFont, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif;\n  --ss-mono: 'Geist Mono', 'SF Mono', ui-monospace, 'SFMono-Regular', Menlo, monospace;\n  --ss-writing: 'Songti SC', 'STSong', 'Noto Serif CJK SC', 'Source Han Serif SC', serif;\n  --ss-ease: cubic-bezier(.22, 1, .36, 1);\n}\n\n.story-studio-app {\n  position: fixed;\n  top: 0;\n  left: 0;\n  width: 100vw;\n  height: 100vh;\n  display: grid;\n  grid-template-rows: auto minmax(0, 1fr);\n  gap: 14px;\n  padding: 40px 14px 14px 14px;\n  background: var(--ss-bg);\n  color: var(--ss-text);\n  font: 14px/1.45 var(--ss-sans);\n  -webkit-font-smoothing: antialiased;\n  z-index: 100;\n  box-sizing: border-box;\n}\n\n.story-studio-app *,\n.story-studio-app *::before,\n.story-studio-app *::after {\n  box-sizing: border-box;\n}\n\n/* ============ \u9876\u680F ============ */\n.ss-topbar {\n  display: grid;\n  grid-template-columns: auto auto minmax(0, 1fr) auto;\n  align-items: center;\n  gap: 12px;\n  min-width: 0;\n  padding: 7px 8px 7px 80px;\n  background: var(--ss-surface);\n  border: 1px solid var(--ss-hairline);\n  border-radius: var(--ss-r-lg);\n  box-shadow: var(--ss-shadow);\n  z-index: 4;\n}\n\n.ss-brand-mark {\n  display: grid;\n  width: 44px;\n  height: 44px;\n  place-items: center;\n  border-radius: 14px;\n  background: linear-gradient(180deg, #0A84FF, #0062C4);\n  color: #fff;\n  font: 800 19px/1 var(--ss-sans);\n  letter-spacing: -.02em;\n  box-shadow: 0 4px 12px rgba(0, 113, 227, .3);\n}\n\n.ss-brand-name {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  min-width: 0;\n  padding: 0 4px 0 2px;\n  color: var(--ss-ink);\n  font-size: 14.5px;\n  font-weight: 700;\n  letter-spacing: -.01em;\n}\n\n.ss-brand-name span {\n  color: var(--ss-brand);\n  font: 600 9px/1 var(--ss-mono);\n  letter-spacing: .14em;\n  text-transform: uppercase;\n  padding: 3px 7px;\n  border-radius: 99px;\n  background: var(--ss-brand-soft);\n}\n\n.ss-project-heading {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  min-width: 0;\n  padding: 0 6px;\n}\n\n.ss-project-heading strong {\n  overflow: hidden;\n  color: var(--ss-ink);\n  font-size: 13.5px;\n  font-weight: 700;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.ss-divider {\n  width: 1px;\n  height: 16px;\n  border-radius: 99px;\n  background: var(--ss-hairline-strong);\n}\n\n.ss-save-state {\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  padding: 5px 11px;\n  border-radius: 99px;\n  background: var(--ss-surface-2);\n  color: var(--ss-muted);\n  font-size: 11px;\n  white-space: nowrap;\n}\n\n.ss-save-state::before {\n  content: \"\";\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background: var(--ss-green);\n  box-shadow: 0 0 0 3px var(--ss-green-soft);\n}\n\n.ss-top-actions {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n}\n\n/* ============ \u6309\u94AE ============ */\n.ss-icon-button,\n.ss-compact-button,\n.ss-primary-button,\n.ss-rail-button,\n.ss-right-tab,\n.ss-right-close,\n.ss-prompt-tool,\n.ss-prompt-model,\n.ss-send-button {\n  border: 0;\n  cursor: pointer;\n  transition: transform 170ms var(--ss-ease), background-color 170ms var(--ss-ease), color 170ms var(--ss-ease), box-shadow 170ms var(--ss-ease);\n}\n\n.ss-icon-button {\n  display: grid;\n  width: 34px;\n  height: 34px;\n  place-items: center;\n  border-radius: 12px;\n  background: transparent;\n  color: var(--ss-muted);\n}\n\n.ss-icon-button:hover {\n  background: var(--ss-bg-2);\n  color: var(--ss-ink);\n}\n\n.ss-icon-button:active {\n  transform: scale(.92);\n}\n\n.ss-compact-button,\n.ss-primary-button {\n  display: inline-flex;\n  min-height: 36px;\n  align-items: center;\n  justify-content: center;\n  gap: 7px;\n  padding: 0 15px;\n  border-radius: 99px;\n  font-size: 12.5px;\n  font-weight: 600;\n}\n\n.ss-compact-button {\n  border: 1px solid var(--ss-hairline);\n  background: var(--ss-surface);\n  color: var(--ss-text);\n}\n\n.ss-compact-button:hover {\n  border-color: var(--ss-hairline-strong);\n  background: var(--ss-surface-2);\n  transform: translateY(-1px);\n}\n\n.ss-primary-button {\n  background: var(--ss-brand);\n  color: #fff;\n  box-shadow: 0 4px 14px rgba(0, 113, 227, .28);\n}\n\n.ss-primary-button:hover {\n  background: var(--ss-brand-hover);\n  transform: translateY(-1px);\n  box-shadow: 0 6px 18px rgba(0, 113, 227, .34);\n}\n\n.ss-ui-icon {\n  width: 16px;\n  height: 16px;\n  fill: none;\n  stroke: currentColor;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n  stroke-width: 1.7;\n}\n\n.ss-nav-icon {\n  width: 19px;\n  height: 19px;\n  fill: none;\n  stroke: currentColor;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n  stroke-width: 1.5;\n}\n\n/* ============ \u5DE5\u4F5C\u533A ============ */\n.ss-workspace {\n  --lib-w: 264px;\n  --right-w: 348px;\n  display: flex;\n  align-items: stretch;\n  min-height: 0;\n  min-width: 0;\n}\n\n/* ============ \u5BFC\u822A\u680F ============ */\n.ss-rail {\n  display: flex;\n  min-height: 0;\n  flex: 0 0 66px;\n  flex-direction: column;\n  align-items: center;\n  gap: 7px;\n  margin-right: 14px;\n  padding: 14px 9px;\n  border-radius: var(--ss-r-card);\n  background: var(--ss-dark);\n  color: #98989D;\n  box-shadow: var(--ss-shadow);\n}\n\n.ss-rail-button {\n  position: relative;\n  display: grid;\n  width: 44px;\n  height: 44px;\n  place-items: center;\n  border: 0;\n  border-radius: 15px;\n  background: transparent;\n  color: inherit;\n  cursor: pointer;\n  transition: color 170ms var(--ss-ease), background-color 170ms var(--ss-ease), transform 170ms var(--ss-ease), box-shadow 170ms var(--ss-ease);\n}\n\n.ss-rail-button:hover {\n  background: rgba(255, 255, 255, .09);\n  color: #F5F5F7;\n  transform: translateY(-1px);\n}\n\n.ss-rail-button.active {\n  background: var(--ss-brand);\n  color: #fff;\n  box-shadow: 0 5px 14px rgba(0, 113, 227, .4);\n}\n\n.ss-rail-spacer {\n  flex: 1;\n}\n\n/* ============ \u9879\u76EE\u5E93 ============ */\n.ss-library {\n  display: grid;\n  min-width: 0;\n  min-height: 0;\n  flex: 0 0 var(--lib-w);\n  grid-template-rows: auto auto minmax(0, 1fr) auto;\n  overflow: hidden;\n  border: 1px solid var(--ss-hairline);\n  border-radius: var(--ss-r-card);\n  background: var(--ss-surface);\n  box-shadow: var(--ss-shadow);\n}\n\n.ss-panel-heading {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  min-height: 54px;\n  padding: 0 10px 0 18px;\n}\n\n.ss-panel-heading h2 {\n  margin: 0;\n  color: var(--ss-ink);\n  font-size: 16px;\n  font-weight: 700;\n  letter-spacing: -.02em;\n}\n\n.ss-project-switcher {\n  margin: 0 12px 14px;\n  padding: 14px;\n  border: 1px solid var(--ss-hairline);\n  border-radius: var(--ss-r-md);\n  background: var(--ss-surface-2);\n}\n\n.ss-project-switcher-top {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.ss-project-cover {\n  display: grid;\n  width: 38px;\n  height: 42px;\n  flex: 0 0 auto;\n  place-items: center;\n  border-radius: 12px 12px 12px 5px;\n  background: var(--ss-dark);\n  color: #fff;\n  font: 700 13px var(--ss-writing);\n  box-shadow: 0 4px 10px rgba(29, 29, 31, .2);\n}\n\n.ss-project-meta {\n  min-width: 0;\n  flex: 1;\n}\n\n.ss-project-meta strong,\n.ss-project-meta span {\n  display: block;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.ss-project-meta strong {\n  color: var(--ss-ink);\n  font-size: 13px;\n  font-weight: 700;\n}\n\n.ss-project-meta span {\n  margin-top: 3px;\n  color: var(--ss-muted);\n  font-size: 11px;\n}\n\n.ss-progress-line {\n  height: 6px;\n  margin-top: 12px;\n  overflow: hidden;\n  border-radius: 99px;\n  background: var(--ss-hairline);\n}\n\n.ss-progress-line span {\n  display: block;\n  height: 100%;\n  border-radius: inherit;\n  background: linear-gradient(90deg, var(--ss-brand), #0A84FF);\n  transition: width 500ms var(--ss-ease);\n}\n\n.ss-library-content {\n  min-height: 0;\n  overflow: auto;\n  padding: 0 10px 14px;\n  scrollbar-width: thin;\n  scrollbar-color: var(--ss-hairline-strong) transparent;\n}\n\n.ss-section-label {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  height: 32px;\n  padding: 0 10px;\n  color: var(--ss-muted);\n  font: 600 10px/1 var(--ss-sans);\n  letter-spacing: .08em;\n  text-transform: uppercase;\n}\n\n.ss-tree-row,\n.ss-library-row {\n  display: flex;\n  min-height: 36px;\n  align-items: center;\n  gap: 8px;\n  width: 100%;\n  padding: 6px 10px;\n  border: 0;\n  border-radius: 12px;\n  background: transparent;\n  color: var(--ss-text);\n  cursor: pointer;\n  text-align: left;\n  transition: background-color 150ms var(--ss-ease), color 150ms var(--ss-ease), transform 150ms var(--ss-ease);\n}\n\n.ss-tree-row:hover,\n.ss-library-row:hover {\n  background: var(--ss-bg-2);\n  color: var(--ss-ink);\n  transform: translateX(2px);\n}\n\n.ss-tree-row.active,\n.ss-library-row.active {\n  background: var(--ss-brand-soft);\n  color: var(--ss-brand-deep);\n  font-weight: 600;\n}\n\n.ss-label {\n  min-width: 0;\n  flex: 1;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.ss-meta {\n  color: var(--ss-faint);\n  font: 500 10.5px/1 var(--ss-mono);\n  white-space: nowrap;\n}\n\n.ss-tree-indent {\n  padding-left: 28px;\n}\n\n.ss-library-footer {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  min-height: 42px;\n  padding: 0 16px;\n  border-top: 1px solid var(--ss-hairline);\n  background: var(--ss-surface-2);\n  color: var(--ss-muted);\n  font-size: 11px;\n}\n\n.ss-status-dot {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background: var(--ss-green);\n  box-shadow: 0 0 0 3px var(--ss-green-soft);\n}\n\n/* ============ \u7F16\u8F91\u5668 ============ */\n.ss-stage {\n  display: grid;\n  min-width: 0;\n  min-height: 0;\n  flex: 1 1 0;\n  grid-template-rows: auto minmax(0, 1fr) auto;\n  overflow: hidden;\n  border: 1px solid var(--ss-hairline);\n  border-radius: var(--ss-r-card);\n  background: var(--ss-surface);\n  box-shadow: var(--ss-shadow);\n}\n\n.ss-editor-toolbar {\n  display: flex;\n  min-width: 0;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 12px;\n  border-bottom: 1px solid var(--ss-hairline);\n  background: var(--ss-surface);\n}\n\n.ss-breadcrumb {\n  min-width: 0;\n  flex: 1;\n  overflow: hidden;\n  color: var(--ss-muted);\n  font-size: 11.5px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.ss-breadcrumb strong {\n  color: var(--ss-text);\n  font-weight: 600;\n}\n\n.ss-editor-scroll {\n  min-height: 0;\n  overflow: auto;\n  padding: 24px 18px 40px;\n  background: var(--ss-bg-2);\n  scrollbar-width: thin;\n  scrollbar-color: var(--ss-hairline-strong) transparent;\n}\n\n.ss-writing-sheet {\n  position: relative;\n  width: 100%;\n  min-height: calc(100vh - 280px);\n  margin: 0 auto;\n  padding: 54px clamp(32px, 5vw, 68px) 84px;\n  border: 1px solid var(--ss-hairline);\n  border-radius: var(--ss-r-lg);\n  background: var(--ss-surface);\n  box-shadow: var(--ss-shadow-paper);\n}\n\n.ss-writing-sheet::before {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  right: 18%;\n  left: 18%;\n  height: 3px;\n  border-radius: 0 0 6px 6px;\n  background: linear-gradient(90deg, var(--ss-brand), #0A84FF);\n}\n\n.ss-document-kicker {\n  color: var(--ss-brand);\n  font: 600 10.5px/1 var(--ss-mono);\n  letter-spacing: .14em;\n  text-transform: uppercase;\n}\n\n.ss-document-title {\n  margin: 14px 0 8px;\n  color: var(--ss-ink);\n  font: 800 30px/1.22 var(--ss-sans);\n  letter-spacing: -.03em;\n}\n\n.ss-document-meta {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 14px;\n  padding-bottom: 26px;\n  border-bottom: 1px solid var(--ss-hairline);\n  color: var(--ss-muted);\n  font-size: 11px;\n}\n\n.ss-document-meta span:first-child {\n  color: var(--ss-brand-deep);\n  font-weight: 700;\n  padding: 4px 11px;\n  border-radius: 99px;\n  background: var(--ss-brand-soft);\n}\n\n.ss-editor-body {\n  margin-top: 30px;\n  color: #2B2B2E;\n  font: 17px/2.1 var(--ss-writing);\n  min-height: 500px;\n}\n\n.ss-stage-footer {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  padding: 0 16px;\n  min-height: 42px;\n  border-top: 1px solid var(--ss-hairline);\n  background: var(--ss-surface-2);\n  color: var(--ss-muted);\n  font: 500 10.5px/1 var(--ss-mono);\n}\n\n.ss-stage-footer span:last-child {\n  margin-left: auto;\n}\n\n/* ============ \u53F3\u4FA7\u9762\u677F ============ */\n.ss-right-panel {\n  display: grid;\n  min-width: 0;\n  min-height: 0;\n  flex: 0 0 var(--right-w);\n  grid-template-rows: auto minmax(0, 1fr);\n  overflow: hidden;\n  border: 1px solid var(--ss-hairline);\n  border-radius: var(--ss-r-card);\n  background: var(--ss-surface);\n  box-shadow: var(--ss-shadow);\n  transition: flex-basis 260ms var(--ss-ease), width 260ms var(--ss-ease), opacity 200ms var(--ss-ease);\n}\n\n.ss-workspace.right-closed .ss-right-panel {\n  display: none;\n}\n\n.ss-right-tabs {\n  display: flex;\n  align-items: stretch;\n  gap: 4px;\n  padding: 8px 10px 0;\n  background: var(--ss-surface-2);\n}\n\n.ss-right-tab {\n  position: relative;\n  flex: 1;\n  min-width: 0;\n  height: 36px;\n  border-radius: 11px;\n  background: transparent;\n  color: var(--ss-muted);\n  font-size: 12px;\n  font-weight: 500;\n}\n\n.ss-right-tab:hover {\n  color: var(--ss-ink);\n  background: rgba(255, 255, 255, .7);\n}\n\n.ss-right-tab.active {\n  background: var(--ss-surface);\n  color: var(--ss-ink);\n  font-weight: 700;\n  box-shadow: var(--ss-shadow-sm);\n}\n\n.ss-right-close {\n  width: 34px;\n  height: 34px;\n  margin-left: 3px;\n  border-radius: 11px;\n  background: transparent;\n  color: var(--ss-muted);\n}\n\n.ss-right-close:hover {\n  background: var(--ss-bg-2);\n  color: var(--ss-ink);\n}\n\n.ss-right-view {\n  display: grid;\n  min-height: 0;\n}\n\n.ss-assistant-view {\n  grid-template-rows: auto minmax(0, 1fr) auto;\n}\n\n.ss-operation-header {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 14px;\n  padding: 16px 18px 14px;\n  border-bottom: 1px solid var(--ss-hairline);\n}\n\n.ss-operation-header strong {\n  display: block;\n  color: var(--ss-ink);\n  font-size: 13.5px;\n  font-weight: 700;\n}\n\n.ss-operation-header div > span {\n  display: block;\n  margin-top: 5px;\n  color: var(--ss-muted);\n  font-size: 11px;\n  line-height: 1.5;\n}\n\n.ss-operation-status {\n  color: var(--ss-green) !important;\n  font-size: 10.5px !important;\n  font-weight: 700;\n  white-space: nowrap;\n  padding: 4px 10px;\n  border-radius: 99px;\n  background: var(--ss-green-soft);\n}\n\n.ss-assistant-scroll {\n  min-height: 0;\n  overflow: auto;\n  padding: 18px 16px 22px;\n  scrollbar-width: thin;\n  scrollbar-color: var(--ss-hairline-strong) transparent;\n}\n\n.ss-thinking-surface {\n  overflow: hidden;\n  border: 1px solid var(--ss-hairline);\n  border-radius: var(--ss-r-md);\n  background: var(--ss-surface-2);\n}\n\n.ss-thinking-steps {\n  position: relative;\n  display: grid;\n  gap: 0;\n  padding: 6px 14px 12px;\n}\n\n.ss-thinking-steps::before {\n  content: \"\";\n  position: absolute;\n  top: 12px;\n  bottom: 22px;\n  left: 25px;\n  width: 1px;\n  background: var(--ss-hairline);\n}\n\n.ss-plan-step {\n  position: relative;\n  display: grid;\n  min-height: 36px;\n  grid-template-columns: 22px minmax(0, 1fr) auto;\n  align-items: center;\n  gap: 8px;\n  color: var(--ss-faint);\n  font-size: 11px;\n  line-height: 1.45;\n}\n\n.ss-plan-step.complete {\n  color: var(--ss-muted);\n}\n\n.ss-plan-step.active {\n  color: var(--ss-ink);\n  font-weight: 600;\n}\n\n.ss-plan-marker {\n  position: relative;\n  display: grid;\n  width: 14px;\n  height: 14px;\n  margin: 0 auto;\n  place-items: center;\n  border: 1px solid var(--ss-hairline-strong);\n  border-radius: 50%;\n  background: var(--ss-surface);\n  color: #fff;\n  z-index: 1;\n}\n\n.ss-plan-marker .ss-ui-icon {\n  width: 9px;\n  height: 9px;\n  stroke-width: 2.6;\n}\n\n.ss-plan-step.complete .ss-plan-marker {\n  border-color: var(--ss-green);\n  background: var(--ss-green);\n}\n\n.ss-plan-step.active .ss-plan-marker {\n  border-color: var(--ss-brand);\n  background: var(--ss-brand);\n  box-shadow: 0 0 0 4px var(--ss-brand-soft);\n}\n\n.ss-plan-step em {\n  color: var(--ss-brand);\n  font-size: 9.5px;\n  font-style: normal;\n  font-weight: 700;\n}\n\n.ss-generation-result {\n  margin-top: 16px;\n  border: 1px solid var(--ss-hairline);\n  border-radius: var(--ss-r-md);\n  background: var(--ss-surface);\n  box-shadow: var(--ss-shadow-sm);\n}\n\n.ss-result-heading {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 14px;\n  color: var(--ss-brand-deep);\n  font-size: 11.5px;\n  font-weight: 700;\n}\n\n.ss-result-heading span:last-child {\n  color: var(--ss-green);\n  font-size: 10px;\n  font-weight: 500;\n  padding: 3px 9px;\n  border-radius: 99px;\n  background: var(--ss-green-soft);\n}\n\n.ss-result-content {\n  position: relative;\n  margin: 0 14px;\n  padding: 12px 14px 12px 21px;\n  border-radius: 12px;\n  background: var(--ss-brand-soft);\n  color: var(--ss-text);\n  font: 13px/1.85 var(--ss-writing);\n}\n\n.ss-result-content::before {\n  content: \"\";\n  position: absolute;\n  top: 12px;\n  bottom: 12px;\n  left: 12px;\n  width: 3px;\n  border-radius: 99px;\n  background: var(--ss-brand);\n}\n\n.ss-result-actions {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 6px;\n  padding: 12px 14px 14px;\n}\n\n.ss-result-actions button {\n  display: inline-flex;\n  min-height: 30px;\n  align-items: center;\n  justify-content: center;\n  gap: 5px;\n  padding: 0 11px;\n  border: 1px solid var(--ss-hairline);\n  border-radius: 99px;\n  background: var(--ss-surface);\n  color: var(--ss-muted);\n  font-size: 11px;\n  cursor: pointer;\n  transition: all 170ms var(--ss-ease);\n}\n\n.ss-result-actions button:hover {\n  border-color: var(--ss-hairline-strong);\n  background: var(--ss-bg-2);\n  color: var(--ss-ink);\n}\n\n.ss-result-actions .ss-accept {\n  grid-column: 1 / -1;\n  min-height: 34px;\n  border-color: transparent;\n  background: var(--ss-brand);\n  color: #fff;\n  box-shadow: 0 4px 12px rgba(0, 113, 227, .26);\n  font-weight: 600;\n}\n\n.ss-result-actions .ss-accept:hover {\n  background: var(--ss-brand-hover);\n}\n\n.ss-prompt-composer {\n  padding: 12px 14px 14px;\n  border-top: 1px solid var(--ss-hairline);\n  background: var(--ss-surface-2);\n}\n\n.ss-prompt-context {\n  display: flex;\n  gap: 9px;\n  margin: 0 3px 8px;\n  color: var(--ss-muted);\n  font-size: 10px;\n}\n\n.ss-prompt-context span {\n  padding: 3px 9px;\n  border-radius: 99px;\n  background: var(--ss-surface);\n}\n\n.ss-prompt-box {\n  padding: 10px 10px 8px 14px;\n  border: 1px solid var(--ss-hairline-strong);\n  border-radius: var(--ss-r-md);\n  background: var(--ss-surface);\n  box-shadow: var(--ss-shadow-sm);\n}\n\n.ss-prompt-box textarea {\n  display: block;\n  width: 100%;\n  height: 40px;\n  resize: none;\n  border: 0;\n  outline: 0;\n  background: transparent;\n  color: var(--ss-text);\n  font-size: 12px;\n  line-height: 1.55;\n  font-family: inherit;\n}\n\n.ss-prompt-box textarea::placeholder {\n  color: var(--ss-faint);\n}\n\n.ss-prompt-footer {\n  display: flex;\n  align-items: center;\n  gap: 3px;\n}\n\n.ss-prompt-tool,\n.ss-prompt-model {\n  height: 28px;\n  border-radius: 9px;\n  background: transparent;\n  color: var(--ss-muted);\n  font-size: 11px;\n}\n\n.ss-prompt-tool {\n  width: 28px;\n}\n\n.ss-prompt-model {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  padding: 0 9px;\n}\n\n.ss-prompt-tool:hover,\n.ss-prompt-model:hover {\n  background: var(--ss-bg-2);\n  color: var(--ss-ink);\n}\n\n.ss-send-button {\n  display: grid;\n  width: 32px;\n  height: 32px;\n  margin-left: auto;\n  place-items: center;\n  border-radius: 12px;\n  background: var(--ss-brand);\n  color: #fff;\n  box-shadow: 0 4px 12px rgba(0, 113, 227, .28);\n}\n\n.ss-send-button:hover {\n  background: var(--ss-brand-hover);\n  transform: translateY(-1px);\n  box-shadow: 0 6px 18px rgba(0, 113, 227, .34);\n}\n\n/* \u672C\u96C6\u8D44\u6599\u89C6\u56FE */\n.ss-context-view,\n.ss-files-view {\n  overflow: auto;\n  padding: 8px 16px 26px;\n  scrollbar-width: thin;\n  scrollbar-color: var(--ss-hairline-strong) transparent;\n}\n\n.ss-context-section {\n  padding: 16px 0 18px;\n  border-bottom: 1px solid var(--ss-hairline);\n}\n\n.ss-context-title {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 11px;\n  color: var(--ss-ink);\n  font-size: 12px;\n  font-weight: 700;\n}\n\n.ss-context-title span {\n  color: var(--ss-muted);\n  font: 500 10px/1 var(--ss-mono);\n}\n\n.ss-character-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 7px 0;\n}\n\n.ss-avatar {\n  display: inline-grid;\n  width: 30px;\n  height: 30px;\n  flex: 0 0 auto;\n  place-items: center;\n  border-radius: 11px;\n  background: var(--ss-brand-soft);\n  color: var(--ss-brand-deep);\n  font: 700 11px var(--ss-writing);\n}\n\n.ss-character-row strong,\n.ss-character-row span {\n  display: block;\n}\n\n.ss-character-row strong {\n  color: var(--ss-text);\n  font-size: 11.5px;\n}\n\n.ss-character-row span {\n  margin-top: 3px;\n  color: var(--ss-muted);\n  font-size: 10px;\n}\n\n/* \u6587\u4EF6\u89C6\u56FE */\n.ss-files-root {\n  margin: 10px 0 14px;\n  padding: 10px 12px;\n  overflow: hidden;\n  border-radius: 12px;\n  background: var(--ss-bg-2);\n  color: var(--ss-muted);\n  font: 400 10px/1.5 var(--ss-mono);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.ss-file-row {\n  min-height: 32px;\n  padding: 8px 11px;\n  border-radius: 11px;\n  color: var(--ss-text);\n  font-size: 11px;\n  cursor: pointer;\n}\n\n.ss-file-row:hover {\n  background: var(--ss-brand-soft);\n  color: var(--ss-brand-deep);\n}\n\n.ss-file-indent-1 {\n  padding-left: 27px;\n}\n\n/* ============ \u5BF9\u8BDD\u6846 ============ */\n.ss-dialog-overlay {\n  position: fixed;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background: rgba(0, 0, 0, 0.4);\n  backdrop-filter: blur(8px);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 9999;\n}\n\n.ss-dialog {\n  width: 90%;\n  max-width: 440px;\n  background: var(--ss-surface);\n  border: 1px solid var(--ss-hairline);\n  border-radius: var(--ss-r-card);\n  box-shadow: var(--ss-shadow-float);\n  animation: ss-dialog-in 200ms var(--ss-ease);\n}\n\n@keyframes ss-dialog-in {\n  from {\n    opacity: 0;\n    transform: scale(0.95) translateY(10px);\n  }\n  to {\n    opacity: 1;\n    transform: scale(1) translateY(0);\n  }\n}\n\n.ss-dialog-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 20px 20px 16px;\n  border-bottom: 1px solid var(--ss-hairline);\n}\n\n.ss-dialog-header h3 {\n  margin: 0;\n  color: var(--ss-ink);\n  font-size: 16px;\n  font-weight: 700;\n}\n\n.ss-dialog-body {\n  padding: 20px;\n}\n\n.ss-dialog-input {\n  width: 100%;\n  padding: 12px 14px;\n  border: 1px solid var(--ss-hairline-strong);\n  border-radius: var(--ss-r-sm);\n  background: var(--ss-surface-2);\n  color: var(--ss-ink);\n  font-size: 14px;\n  font-family: inherit;\n  outline: none;\n  transition: border-color 170ms var(--ss-ease), background-color 170ms var(--ss-ease);\n}\n\n.ss-dialog-input:focus {\n  border-color: var(--ss-brand);\n  background: var(--ss-surface);\n}\n\n.ss-dialog-input::placeholder {\n  color: var(--ss-faint);\n}\n\n.ss-dialog-footer {\n  display: flex;\n  gap: 8px;\n  justify-content: flex-end;\n  padding: 16px 20px 20px;\n  border-top: 1px solid var(--ss-hairline);\n}\n\n.ss-section-action {\n  border: 0;\n  background: transparent;\n  color: var(--ss-brand);\n  font-size: 18px;\n  font-weight: 700;\n  cursor: pointer;\n  padding: 4px 8px;\n  line-height: 1;\n  transition: color 170ms var(--ss-ease), background-color 170ms var(--ss-ease);\n}\n\n.ss-section-action:hover {\n  color: var(--ss-brand-hover);\n  background: var(--ss-brand-soft);\n  border-radius: 6px;\n}\n";
